import json
from datetime import datetime

MENU = [
    {'id': '1', 'name': '蛋餅', 'price': 30},
    {'id': '2', 'name': '漢堡', 'price': 45},
    {'id': '3', 'name': '三明治', 'price': 40},
    {'id': '4', 'name': '奶茶', 'price': 25},
    {'id': '5', 'name': '豆漿', 'price': 20},
]
MENU_BY_ID = {m['id']: m for m in MENU}

ORDERS = []
_counter = [0]

STATUSES = ('pending', 'preparing', 'done')
ORDER_TYPES = ('dine_in', 'take_out')
MAX_QTY = 99


def _err(status, msg):
    return status, {'error': msg}


def _parse(body):
    if not body:
        return None, '請提供 JSON 內容'
    try:
        data = json.loads(body.decode('utf-8'))
    except (ValueError, UnicodeDecodeError):
        return None, '內容不是有效的 JSON'
    if not isinstance(data, dict):
        return None, '請求內容必須是 JSON 物件'
    return data, None


def _copy_order(o):
    return {
        'id': o['id'],
        'items': [dict(i) for i in o['items']],
        'order_type': o['order_type'],
        'table_number': o['table_number'],
        'status': o['status'],
        'total': o['total'],
        'created_at': o['created_at'],
    }


def _get_menu():
    return 200, {'items': [dict(m) for m in MENU]}


def _create_order(body):
    data, err = _parse(body)
    if err:
        return _err(400, err)
    items_in = data.get('items')
    if not isinstance(items_in, list) or not items_in:
        return _err(400, '請至少選擇一項餐點')
    merged = {}
    for it in items_in:
        if not isinstance(it, dict):
            return _err(400, '品項格式不正確')
        mid = it.get('menu_item_id')
        if isinstance(mid, bool) or not isinstance(mid, (str, int)):
            return _err(400, '品項缺少有效的餐點編號')
        mid = str(mid).strip()
        if mid not in MENU_BY_ID:
            return _err(400, '找不到餐點：' + mid)
        qty = it.get('quantity')
        if isinstance(qty, float) and qty.is_integer():
            qty = int(qty)
        if isinstance(qty, bool) or not isinstance(qty, int) or qty < 1:
            return _err(400, '數量必須是大於 0 的整數')
        merged[mid] = merged.get(mid, 0) + qty
        if merged[mid] > MAX_QTY:
            return _err(400, '單一餐點數量不可超過 ' + str(MAX_QTY))
    order_type = data.get('order_type')
    if order_type not in ORDER_TYPES:
        return _err(400, '用餐方式必須是內用或外帶')
    table = data.get('table_number', '')
    if table is None:
        table = ''
    if isinstance(table, bool) or not isinstance(table, (str, int)):
        return _err(400, '桌號格式不正確')
    table = str(table).strip()
    if len(table) > 20:
        return _err(400, '桌號太長')
    if order_type == 'dine_in' and not table:
        return _err(400, '內用必須填寫桌號')
    lines = []
    total = 0
    for mid, qty in merged.items():
        m = MENU_BY_ID[mid]
        lines.append({
            'menu_item_id': mid,
            'name': m['name'],
            'price': m['price'],
            'quantity': qty,
        })
        total += m['price'] * qty
    _counter[0] += 1
    order = {
        'id': str(_counter[0]),
        'items': lines,
        'order_type': order_type,
        'table_number': table,
        'status': 'pending',
        'total': total,
        'created_at': datetime.now().isoformat(timespec='seconds'),
    }
    ORDERS.append(order)
    return 201, _copy_order(order)


def _list_orders():
    ordered = sorted(ORDERS, key=lambda o: (o['created_at'], int(o['id'])))
    return 200, {'items': [_copy_order(o) for o in ordered]}


def _update_order(order_id, body):
    order = None
    for o in ORDERS:
        if o['id'] == order_id:
            order = o
            break
    if order is None:
        return _err(404, '找不到這筆訂單')
    data, err = _parse(body)
    if err:
        return _err(400, err)
    status = data.get('status')
    if not isinstance(status, str) or status not in STATUSES:
        return _err(400, '狀態必須是 pending、preparing 或 done')
    order['status'] = status
    return 200, _copy_order(order)


def _stats_today():
    today = datetime.now().date().isoformat()
    count = 0
    amount = 0
    agg = {}
    for o in ORDERS:
        if not o['created_at'].startswith(today):
            continue
        count += 1
        amount += o['total']
        for i in o['items']:
            rec = agg.setdefault(i['menu_item_id'], {
                'menu_item_id': i['menu_item_id'],
                'name': i['name'],
                'quantity': 0,
            })
            rec['quantity'] += i['quantity']
    top = sorted(agg.values(), key=lambda r: (-r['quantity'], int(r['menu_item_id'])))[:3]
    return 200, {'order_count': count, 'total_amount': amount, 'top_items': top}


def handle(method, path, body):
    method = (method or '').upper()
    path = (path or '').split('?')[0]
    if not path.startswith('/'):
        path = '/' + path
    while len(path) > 1 and path.endswith('/'):
        path = path[:-1]

    if path == '/menu':
        if method == 'GET':
            return _get_menu()
        return _err(405, '不支援此請求方法')
    if path == '/orders':
        if method == 'GET':
            return _list_orders()
        if method == 'POST':
            return _create_order(body)
        return _err(405, '不支援此請求方法')
    if path.startswith('/orders/'):
        order_id = path[len('/orders/'):]
        if order_id and '/' not in order_id:
            if method == 'PATCH':
                return _update_order(order_id, body)
            return _err(405, '不支援此請求方法')
        return _err(404, '找不到此路徑')
    if path == '/stats/today':
        if method == 'GET':
            return _stats_today()
        return _err(405, '不支援此請求方法')
    return _err(404, '找不到此路徑')

