(function () {
'use strict';
var STATUS_LABEL = { pending: '待做', preparing: '製作中', done: '完成' };
var STATUS_ORDER = ['pending', 'preparing', 'done'];
var TYPE_LABEL = { dine_in: '內用', take_out: '外帶' };
var menu = [];
var qty = {};
var currentTab = 'order';
var kitchenTimer = null;
var submitting = false;

function $(id) { return document.getElementById(id); }

function el(tag, className, text) {
  var e = document.createElement(tag);
  if (className) { e.className = className; }
  if (text !== undefined && text !== null) { e.textContent = text; }
  return e;
}

function money(n) { return '$' + Number(n || 0); }

function showMsg(node, text, type) {
  node.textContent = text || '';
  node.className = 'msg' + (text && type ? ' ' + type : '');
}

function api(method, path, body) {
  var opts = { method: method, headers: {} };
  if (body !== undefined) {
    opts.headers['Content-Type'] = 'application/json';
    opts.body = JSON.stringify(body);
  }
  return fetch('api/' + path, opts).then(function (res) {
    return res.text().then(function (text) {
      var data = null;
      try { data = text ? JSON.parse(text) : null; } catch (e) { data = null; }
      if (!res.ok) {
        var msg = data && data.error ? String(data.error) : '請求失敗（狀態碼 ' + res.status + '）';
        throw new Error(msg);
      }
      if (data === null || typeof data !== 'object') {
        throw new Error('伺服器回應格式錯誤');
      }
      return data;
    });
  }, function () {
    throw new Error('無法連線到伺服器，請稍後再試');
  });
}

/* ---------- 分頁導覽 ---------- */
function switchTab(name) {
  currentTab = name;
  var tabs = document.querySelectorAll('#tabs .tab');
  for (var i = 0; i < tabs.length; i++) {
    tabs[i].classList.toggle('active', tabs[i].getAttribute('data-tab') === name);
  }
  ['order', 'kitchen', 'stats'].forEach(function (v) {
    $('view-' + v).classList.toggle('hidden', v !== name);
  });
  if (kitchenTimer) { clearInterval(kitchenTimer); kitchenTimer = null; }
  if (name === 'order') {
    loadMenu();
  } else if (name === 'kitchen') {
    loadOrders();
    kitchenTimer = setInterval(function () {
      if (currentTab === 'kitchen') { loadOrders(true); }
    }, 10000);
  } else if (name === 'stats') {
    loadStats();
  }
}

/* ---------- 點餐 ---------- */
function loadMenu() {
  return api('GET', 'menu').then(function (data) {
    menu = Array.isArray(data.items) ? data.items : [];
    renderMenu();
    renderCart();
  }).catch(function (err) {
    var box = $('menu-list');
    box.textContent = '';
    box.appendChild(el('p', 'msg error', '無法載入菜單：' + err.message));
  });
}

function renderMenu() {
  var box = $('menu-list');
  box.textContent = '';
  if (!menu.length) {
    box.appendChild(el('p', 'muted', '目前沒有可點的餐點'));
    return;
  }
  menu.forEach(function (m) {
    var id = String(m.id);
    var row = el('div', 'menu-item');
    var info = el('div', 'menu-info');
    info.appendChild(el('span', 'menu-name', m.name));
    info.appendChild(el('span', 'menu-price', money(m.price)));
    row.appendChild(info);
    var ctl = el('div', 'qty-ctl');
    var minus = el('button', 'qty-btn', '−');
    minus.type = 'button';
    minus.setAttribute('data-id', id);
    minus.setAttribute('data-delta', '-1');
    minus.setAttribute('aria-label', '減少 ' + m.name);
    var num = el('span', 'qty-num', String(qty[id] || 0));
    var plus = el('button', 'qty-btn', '+');
    plus.type = 'button';
    plus.setAttribute('data-id', id);
    plus.setAttribute('data-delta', '1');
    plus.setAttribute('aria-label', '增加 ' + m.name);
    ctl.appendChild(minus);
    ctl.appendChild(num);
    ctl.appendChild(plus);
    row.appendChild(ctl);
    box.appendChild(row);
  });
}

function renderCart() {
  var list = $('cart-list');
  list.textContent = '';
  var total = 0;
  var count = 0;
  menu.forEach(function (m) {
    var q = qty[String(m.id)] || 0;
    if (q > 0) {
      count++;
      var sub = Number(m.price) * q;
      total += sub;
      var li = el('li', 'cart-row');
      li.appendChild(el('span', '', m.name + ' × ' + q));
      li.appendChild(el('span', '', money(sub)));
      list.appendChild(li);
    }
  });
  if (!count) {
    list.appendChild(el('li', 'muted', '尚未選擇餐點'));
  }
  $('cart-total').textContent = money(total);
}

function changeQty(id, delta) {
  var q = (qty[id] || 0) + delta;
  if (q < 0) { q = 0; }
  if (q > 99) { q = 99; }
  qty[id] = q;
  renderMenu();
  renderCart();
}

function selectedType() {
  var r = document.querySelector('input[name="order_type"]:checked');
  return r ? r.value : 'dine_in';
}

function updateTableLabel() {
  $('table-label').textContent = selectedType() === 'dine_in' ? '桌號（內用必填）' : '桌號（外帶可留空）';
}

function submitOrder() {
  if (submitting) { return; }
  var msg = $('order-msg');
  var items = [];
  menu.forEach(function (m) {
    var q = qty[String(m.id)] || 0;
    if (q > 0) { items.push({ menu_item_id: String(m.id), quantity: q }); }
  });
  var type = selectedType();
  var table = $('table-number').value.trim();
  if (!items.length) {
    showMsg(msg, '請至少選擇一項餐點', 'error');
    return;
  }
  if (type === 'dine_in' && !table) {
    showMsg(msg, '內用請填寫桌號', 'error');
    $('table-number').focus();
    return;
  }
  submitting = true;
  $('submit-order').disabled = true;
  showMsg(msg, '送出中…', '');
  api('POST', 'orders', { items: items, order_type: type, table_number: table }).then(function (order) {
    qty = {};
    $('table-number').value = '';
    renderMenu();
    renderCart();
    showMsg(msg, '訂單已送出（編號 ' + order.id + '，合計 ' + money(order.total) + '）', 'success');
  }).catch(function (err) {
    showMsg(msg, '送出失敗：' + err.message, 'error');
  }).then(function () {
    submitting = false;
    $('submit-order').disabled = false;
  });
}

/* ---------- 廚房 ---------- */
function formatTime(s) {
  if (!s) { return ''; }
  return String(s).replace('T', ' ').slice(0, 16);
}

function loadOrders(silent) {
  return api('GET', 'orders').then(function (data) {
    showMsg($('kitchen-msg'), '', '');
    renderOrders(Array.isArray(data.items) ? data.items : []);
  }).catch(function (err) {
    showMsg($('kitchen-msg'), '無法載入訂單：' + err.message, 'error');
  });
}

function renderOrders(orders) {
  var box = $('orders-list');
  box.textContent = '';
  if (!orders.length) {
    box.appendChild(el('p', 'muted', '目前沒有訂單'));
    return;
  }
  orders.forEach(function (o) {
    var status = STATUS_ORDER.indexOf(o.status) >= 0 ? o.status : 'pending';
    var card = el('article', 'order-card status-' + status);
    var head = el('div', 'order-head');
    var title = '#' + o.id + ' ' + (TYPE_LABEL[o.order_type] || o.order_type || '');
    if (o.table_number) { title += '・桌號 ' + o.table_number; }
    head.appendChild(el('strong', '', title));
    head.appendChild(el('span', 'badge badge-' + status, STATUS_LABEL[o.status] || o.status));
    card.appendChild(head);
    card.appendChild(el('div', 'order-time', formatTime(o.created_at)));
    var ul = el('ul', 'order-items');
    (o.items || []).forEach(function (it) {
      ul.appendChild(el('li', '', it.name + ' × ' + it.quantity + '（' + money(it.price) + '）'));
    });
    card.appendChild(ul);
    card.appendChild(el('div', 'order-total', '合計：' + money(o.total)));
    var actions = el('div', 'order-actions');
    STATUS_ORDER.forEach(function (s) {
      var b = el('button', 'status-btn btn-' + s + (s === o.status ? ' current' : ''), STATUS_LABEL[s]);
      b.type = 'button';
      b.setAttribute('data-id', String(o.id));
      b.setAttribute('data-status', s);
      if (s === o.status) { b.disabled = true; }
      actions.appendChild(b);
    });
    card.appendChild(actions);
    box.appendChild(card);
  });
}

function updateStatus(id, status) {
  api('PATCH', 'orders/' + encodeURIComponent(id), { status: status }).then(function () {
    return loadOrders();
  }).catch(function (err) {
    showMsg($('kitchen-msg'), '更新狀態失敗：' + err.message, 'error');
  });
}

/* ---------- 營業額 ---------- */
function loadStats() {
  return api('GET', 'stats/today').then(function (d) {
    showMsg($('stats-msg'), '', '');
    $('stat-count').textContent = String(d.order_count != null ? d.order_count : 0);
    $('stat-amount').textContent = money(d.total_amount);
    var ol = $('stat-top');
    ol.textContent = '';
    var top = Array.isArray(d.top_items) ? d.top_items : [];
    if (!top.length) {
      ol.appendChild(el('li', 'muted', '今天還沒有資料'));
    }
    top.forEach(function (t) {
      ol.appendChild(el('li', '', t.name + '：' + t.quantity + ' 份'));
    });
  }).catch(function (err) {
    showMsg($('stats-msg'), '無法載入營業額：' + err.message, 'error');
  });
}

/* ---------- 事件 ---------- */
$('tabs').addEventListener('click', function (e) {
  var t = e.target.closest('.tab');
  if (t) { switchTab(t.getAttribute('data-tab')); }
});
$('menu-list').addEventListener('click', function (e) {
  var b = e.target.closest('.qty-btn');
  if (b) { changeQty(b.getAttribute('data-id'), Number(b.getAttribute('data-delta'))); }
});
var radios = document.querySelectorAll('input[name="order_type"]');
for (var i = 0; i < radios.length; i++) {
  radios[i].addEventListener('change', updateTableLabel);
}
$('submit-order').addEventListener('click', submitOrder);
$('orders-list').addEventListener('click', function (e) {
  var b = e.target.closest('.status-btn');
  if (b && !b.disabled) { updateStatus(b.getAttribute('data-id'), b.getAttribute('data-status')); }
});
$('refresh-orders').addEventListener('click', function () { loadOrders(); });
$('refresh-stats').addEventListener('click', function () { loadStats(); });

updateTableLabel();
switchTab('order');
})();

