* { box-sizing: border-box; }
body { margin: 0; font-family: system-ui, -apple-system, 'Noto Sans TC', 'Microsoft JhengHei', sans-serif; background: #faf6ef; color: #333; font-size: 17px; }
.app-header { background: #c9791b; color: #fff; padding: 12px 16px 0; }
.app-header h1 { margin: 0 0 10px; font-size: 1.4rem; }
.tabs { display: flex; gap: 6px; }
.tab { flex: 1; padding: 14px 8px; font-size: 1.05rem; border: none; border-radius: 10px 10px 0 0; background: #e3a65a; color: #fff; cursor: pointer; }
.tab.active { background: #faf6ef; color: #8a4f0c; font-weight: bold; }
main { max-width: 900px; margin: 0 auto; padding: 16px; }
.hidden { display: none; }
h2 { font-size: 1.2rem; margin: 8px 0 12px; }
h3 { margin: 0 0 8px; }
.muted { color: #888; }
.panel { background: #fff; border-radius: 12px; padding: 16px; margin-top: 16px; box-shadow: 0 1px 4px rgba(0,0,0,0.1); }
.menu-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(260px, 1fr)); gap: 10px; }
.menu-item { display: flex; justify-content: space-between; align-items: center; background: #fff; border-radius: 12px; padding: 12px 14px; box-shadow: 0 1px 4px rgba(0,0,0,0.1); }
.menu-info { display: flex; flex-direction: column; }
.menu-name { font-weight: bold; font-size: 1.1rem; }
.menu-price { color: #c9791b; }
.qty-ctl { display: flex; align-items: center; gap: 10px; }
.qty-btn { width: 44px; height: 44px; font-size: 1.5rem; border: none; border-radius: 50%; background: #c9791b; color: #fff; cursor: pointer; }
.qty-btn:active { background: #8a4f0c; }
.qty-num { min-width: 28px; text-align: center; font-size: 1.2rem; }
.cart-list { list-style: none; padding: 0; margin: 0 0 8px; }
.cart-row { display: flex; justify-content: space-between; padding: 6px 0; border-bottom: 1px dashed #ddd; }
.total { font-size: 1.2rem; text-align: right; }
.field { margin: 12px 0; }
.label { display: block; margin-bottom: 6px; font-weight: bold; }
.choice { display: inline-block; margin-right: 18px; padding: 8px 0; cursor: pointer; }
.choice input { width: 20px; height: 20px; vertical-align: middle; }
input[type=text] { width: 100%; padding: 12px; font-size: 1.1rem; border: 1px solid #bbb; border-radius: 8px; }
button { font-family: inherit; }
.primary { width: 100%; padding: 16px; font-size: 1.2rem; border: none; border-radius: 10px; background: #2e7d32; color: #fff; cursor: pointer; }
.primary:disabled { background: #9bb99d; }
.toolbar { display: flex; justify-content: space-between; align-items: center; }
.toolbar button { padding: 10px 16px; font-size: 1rem; border: 1px solid #c9791b; background: #fff; color: #8a4f0c; border-radius: 8px; cursor: pointer; }
.msg { margin: 10px 0; min-height: 1.2em; }
.msg.error { color: #b71c1c; background: #fdecea; padding: 10px; border-radius: 8px; }
.msg.success { color: #1b5e20; background: #e8f5e9; padding: 10px; border-radius: 8px; }
.orders-list { display: grid; grid-template-columns: repeat(auto-fill, minmax(280px, 1fr)); gap: 12px; }
.order-card { background: #fff; border-radius: 12px; padding: 14px; border-left: 8px solid #999; box-shadow: 0 1px 4px rgba(0,0,0,0.1); }
.order-card.status-pending { border-left-color: #d32f2f; }
.order-card.status-preparing { border-left-color: #f9a825; }
.order-card.status-done { border-left-color: #2e7d32; opacity: 0.8; }
.order-head { display: flex; justify-content: space-between; align-items: center; gap: 8px; }
.order-time { color: #777; font-size: 0.9rem; margin: 4px 0; }
.order-items { margin: 8px 0; padding-left: 20px; }
.order-total { font-weight: bold; margin-bottom: 8px; }
.badge { padding: 3px 10px; border-radius: 12px; color: #fff; font-size: 0.9rem; white-space: nowrap; }
.badge-pending { background: #d32f2f; }
.badge-preparing { background: #f9a825; color: #333; }
.badge-done { background: #2e7d32; }
.order-actions { display: flex; gap: 6px; }
.status-btn { flex: 1; padding: 12px 4px; font-size: 1rem; border: 2px solid #999; background: #fff; border-radius: 8px; cursor: pointer; }
.btn-pending { border-color: #d32f2f; color: #d32f2f; }
.btn-preparing { border-color: #f9a825; color: #8a6100; }
.btn-done { border-color: #2e7d32; color: #2e7d32; }
.btn-pending.current { background: #d32f2f; color: #fff; }
.btn-preparing.current { background: #f9a825; color: #333; }
