.stat-cards { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; }
.stat-card { background: #fff; border-radius: 12px; padding: 18px; text-align: center; box-shadow: 0 1px 4px rgba(0,0,0,0.1); }
.stat-label { display: block; color: #777; margin-bottom: 6px; }
.stat-card strong { font-size: 1.8rem; color: #c9791b; }
.top-list { margin: 0; padding-left: 24px; font-size: 1.1rem; line-height: 1.8; }
@media (max-width: 480px) {
  body { font-size: 16px; }
  main { padding: 10px; }
}
